{
  "packet_id": "H6-T04-2",
  "claim_id": "C048",
  "status": "SUPPORTED",
  "claim": {
    "component_id": "C048.main",
    "value": "Intended roster dates can change.",
    "scope": "Uncertainty in stated timing intentions, not a report that a particular date has changed.",
    "provenance": {
      "refs": [
        {
          "source_id": "P024",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "P024 explicitly supplies the possibility of changing intended roster dates."
    }
  },
  "signal_basis": {
    "component_id": "C048.signal_basis",
    "value": "Customer follow-ups document intended roster timing, with retrospective reports and unknowns labeled; a documented wait until a stated roster date explains an interval, while silence does not establish postponement.",
    "scope": "Proposed observations of reported timing intentions, assumed observed for this judgment; they do not establish that any particular date changed.",
    "provenance": {
      "refs": [
        {
          "source_id": "P004",
          "role": "SUPPORT"
        },
        {
          "source_id": "P014",
          "role": "SUPPORT"
        },
        {
          "source_id": "P016",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "These spans supply the timing documentation, its interpretive limits, and its status as proposed observation."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C048.stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
      "rationale": "No unresolved empirical relation is required for this bounded possibility claim."
    }
  },
  "rationale": "A stated intention is revisable. Recording it supports treating the date as intended timing without guaranteeing that it remains fixed. The claim expresses this ordinary limitation and does not infer an actual change from the observed record.",
  "uncertainty": "Whether any particular roster date changes, and how frequently dates change, remains unestablished.",
  "anomalies": []
}
